#include <nlohmann/json.hpp>
#include <cstdio>
#include <iostream>
int main() {
    std::FILE* f = std::tmpfile();
    if (!f) return 0;
    std::fputs("123", f);
    std::rewind(f);
    std::ungetc('[', f);
    // The stream now effectively starts with '[123' if we re-adjust or if ungetc places it
    // Actually standard ungetc allows pushing back one character before the file position.
    try {
        // Let's test standard parse with an ungetc'd character if supported
        std::rewind(f);
        std::fgetc(f);
        std::ungetc('{', f);
        // Now reading should encounter '{'
        auto j = nlohmann::json::parse(f);
        std::cout << j.dump() << std::endl;
    } catch (const std::exception& e) {
        std::cout << "Exception: " << e.what() << std::endl;
    }
    std::fclose(f);
}
